### mini_pkg.core.Registry.register
signature: register(self, name, value)
    def register(self, name, value):
        if name in self._items:
            raise KeyError(f"already registered: {name}")
        self._items[name] = value

### mini_pkg.core.dedupe
signature: dedupe(items)
def dedupe(items):
    """Return items with duplicates removed, preserving first-seen order."""
    seen = set()
    out = []
    for item in items:
        if item not in seen:
            seen.add(item)
            out.append(item)
    return out

### mini_pkg.core.first
signature: first(items, pred, default=None)
def first(items, pred, default=None):
    """Return the first item for which pred(item) is true, else default."""
    for item in items:
        if pred(item):
            return item
    return default
